#!/usr/bin/env bash
# Push gate for the own-your-diff skill. A commit may be pushed only after its
# author passed a quiz on it. Passes are stored as `git patch-id --stable`
# values, so rebases, rewords, and squashes of quizzed work stay quizzed.
set -euo pipefail

EMPTY_TREE=$(git hash-object -t tree /dev/null)
ZERO=0000000000000000000000000000000000000000

usage() {
  cat <<'EOF'
usage: quizgate <command>
  pending    unquizzed commits a push of HEAD would send, oldest first
  base       commit the explainer diffs from (parent of the oldest pending commit)
  dir        directory holding explainers, quiz transcripts, and the ledger
  record --by human|agent
             mark every pending commit, and their combined diff, as quizzed
  open FILE  open an explainer in the browser
  check      pre-push hook entry point; reads pushed refs on stdin
  install    opt this repo in: write .own-your-diff and the pre-push hook
  sync       copy quizgate to $QUIZGATE_BIN (default ~/.local/bin), and
             install the hook in an opted-in repo that lacks it
EOF
}

state_dir() {
  local d
  d="$(git rev-parse --path-format=absolute --git-common-dir)/own-your-diff"
  mkdir -p "$d"
  echo "$d"
}

ledger() { local f; f="$(state_dir)/ledger"; touch "$f"; echo "$f"; }

commit_pid() { git show --no-color --format= "$1" | git patch-id --stable | cut -d' ' -f1; }

range_pid() { git diff --no-color "$1" "$2" | git patch-id --stable | cut -d' ' -f1; }

quizzed() { grep -q "^$1"$'\t' "$(ledger)"; }

# Commits reachable from $1 that no remote has, oldest first. A commit with an
# empty diff has no patch-id and needs no quiz.
unpushed() { git rev-list --reverse --no-merges "$1" --not --remotes; }

unquizzed() {
  local c pid
  for c in $(unpushed "$1"); do
    pid=$(commit_pid "$c")
    [[ -z "$pid" ]] && continue
    quizzed "$pid" || echo "$c"
  done
}

cmd_pending() { unquizzed HEAD | xargs -r git log --no-walk=unsorted --format='%h %s'; }

cmd_base() {
  local pending oldest
  pending=$(unquizzed HEAD)
  oldest=${pending%%$'\n'*}
  [[ -z "$oldest" ]] && { echo "nothing pending" >&2; exit 1; }
  git rev-parse --verify -q "$oldest^" || echo "$EMPTY_TREE"
}

cmd_record() {
  local by commits c pid base now
  [[ "${1:-}" == --by && "${2:-}" =~ ^(human|agent)$ ]] || { echo "usage: quizgate record --by human|agent" >&2; exit 2; }
  by=$2
  commits=$(unquizzed HEAD)
  [[ -z "$commits" ]] && { echo "nothing pending"; return; }
  base=$(cmd_base)
  now=$(date -u +%FT%TZ)
  {
    for c in $commits; do
      printf '%s\t%s\t%s\tcommit\t%s\n' "$(commit_pid "$c")" "$(git rev-parse --short "$c")" "$now" "$by"
    done
    pid=$(range_pid "$base" HEAD)
    [[ -n "$pid" ]] && printf '%s\t%s\t%s\trange\t%s\n' "$pid" "$(git rev-parse --short HEAD)" "$now" "$by"
  } >>"$(ledger)"
  echo "recorded $(wc -w <<<"$commits") commit(s) as quizzed by $by"
}

cmd_open() {
  local f=${1:?usage: quizgate open FILE}
  if command -v wslview >/dev/null; then wslview "$f"
  elif command -v explorer.exe >/dev/null; then explorer.exe "$(wslpath -w "$f")" || true
  elif command -v xdg-open >/dev/null; then xdg-open "$f"
  elif command -v open >/dev/null; then open "$f"
  else echo "open $f in a browser"
  fi
}

cmd_check() {
  local local_ref local_sha remote_ref remote_sha missing=""
  while read -r local_ref local_sha remote_ref remote_sha; do
    [[ "$local_sha" == "$ZERO" ]] && continue
    missing+=$(unquizzed "$local_sha")$'\n'
  done
  missing=$(sort -u <<<"$missing" | sed '/^$/d')
  [[ -z "$missing" ]] && exit 0
  {
    echo "own-your-diff: push blocked. These commits have no passed quiz:"
    xargs git log --no-walk --format='  %h %s' <<<"$missing"
    echo "Ask your agent to run the own-your-diff skill, read the explainer, and pass the quiz."
  } >&2
  exit 1
}

HOOK_TAG="# own-your-diff pre-push hook"

hook_path() { echo "$(git rev-parse --path-format=absolute --git-path hooks)/pre-push"; }

write_hook() {
  local hook hooks_path
  hooks_path=$(git config core.hooksPath) || true
  if [[ -n "$hooks_path" ]]; then
    echo "own-your-diff: core.hooksPath=$hooks_path manages this repo's hooks. Add this line to its pre-push hook: quizgate check || exit 1" >&2
    return 1
  fi
  hook=$(hook_path)
  grep -qF "$HOOK_TAG" "$hook" 2>/dev/null && return
  if [[ -e "$hook" ]]; then
    echo "own-your-diff: $hook already exists. Add this line to it: quizgate check || exit 1" >&2
    return 1
  fi
  mkdir -p "$(dirname "$hook")"
  cat >"$hook" <<'HOOK'
#!/bin/sh
# own-your-diff pre-push hook
gate=$(command -v quizgate || echo "$HOME/.local/bin/quizgate")
[ -x "$gate" ] || { echo "own-your-diff: push blocked. quizgate is not installed, see https://github.com/krimvp/own-your-diff" >&2; exit 1; }
exec "$gate" check
HOOK
  chmod +x "$hook"
  echo "installed $hook"
}

cmd_install() {
  local marker
  marker="$(git rev-parse --show-toplevel)/.own-your-diff"
  [[ -e "$marker" ]] || { echo "Pushes from this repo need a passed own-your-diff quiz." >"$marker"; echo "wrote $marker, commit it"; }
  write_hook
}

cmd_sync() {
  local bin=${QUIZGATE_BIN:-$HOME/.local/bin} top hooks_path
  mkdir -p "$bin"
  cmp -s "$0" "$bin/quizgate" || install -m 755 "$0" "$bin/quizgate"
  top=$(git rev-parse --show-toplevel 2>/dev/null) || return 0
  [[ -e "$top/.own-your-diff" ]] || return 0
  hooks_path=$(git config --local core.hooksPath) || true
  if [[ -n "$hooks_path" && ! -d "$(cd "$top" && realpath -m "$hooks_path")" ]]; then
    git config --local --unset core.hooksPath
    echo "own-your-diff: unset core.hooksPath=$hooks_path, which pointed at a missing directory"
  fi
  write_hook >/dev/null || true
}

case "${1:-}" in
  pending) cmd_pending ;;
  base) cmd_base ;;
  dir) state_dir ;;
  record) shift; cmd_record "$@" ;;
  open) shift; cmd_open "$@" ;;
  check) cmd_check ;;
  install) cmd_install ;;
  sync) cmd_sync ;;
  *) usage; exit 2 ;;
esac

#!/usr/bin/env python3
"""Check a quiz file against the shape in references/quiz-file.md.

usage: quizlint [--plan] FILE
  --plan   the quiz has not run yet: no attempts and no outcome
"""
import json
import sys

ALTITUDES = {"design", "mechanism", "trivial"}
KINDS = {"single", "multi", "free"}
CATEGORIES = {"rationale", "failure", "extension", "boundary", "flow", "invalidation", "measurement"}
VERDICTS = {"pass", "vague", "wrong"}
TOP_KEYS = {"version", "branch", "base", "head", "target", "altitude", "incidental",
            "examinee", "questions", "outcome", "findings"}
QUESTION_KEYS = {"id", "kind", "category", "prompt", "options", "key_points", "attempts"}
ATTEMPT_KEYS = {"prompt", "kind", "options", "answer", "verdict", "feedback", "round"}
MAX_QUESTIONS = 10


def text(value):
    return isinstance(value, str) and value.strip() != ""


def check_options(where, kind, options, problems):
    if kind == "free":
        if options:
            problems.append(f"{where}: a free question has no options")
        return
    low, high = (2, 4) if kind == "single" else (3, 4)
    if not isinstance(options, list) or not low <= len(options) <= high:
        problems.append(f"{where}: a {kind} question has {low} to {high} options")
        return
    labels = [o.get("label") for o in options if isinstance(o, dict)]
    if len(labels) != len(options) or not all(text(label) for label in labels):
        problems.append(f"{where}: every option is {{\"label\": text, \"correct\": bool}}")
        return
    if len(set(labels)) != len(labels):
        problems.append(f"{where}: option labels repeat")
    correct = [o for o in options if o.get("correct") is True]
    if any(not isinstance(o.get("correct"), bool) for o in options):
        problems.append(f"{where}: every option says whether it is correct")
    if kind == "single" and len(correct) != 1:
        problems.append(f"{where}: a single question has exactly one correct option, not {len(correct)}")
    if kind == "multi" and not correct:
        problems.append(f"{where}: a multi question has at least one correct option")


def lint(quiz, plan):
    problems = []
    if not isinstance(quiz, dict):
        return ["the quiz file holds one JSON object"]
    for key in sorted(set(quiz) - TOP_KEYS):
        problems.append(f"unknown key {key!r}")
    if quiz.get("version") != 1:
        problems.append("version is 1")
    for key in ("branch", "base", "head", "target"):
        if not text(quiz.get(key)):
            problems.append(f"{key} is a non-empty string")
    if quiz.get("altitude") not in ALTITUDES:
        problems.append(f"altitude is one of {sorted(ALTITUDES)}")
    incidental = quiz.get("incidental", [])
    if not isinstance(incidental, list) or not all(text(i) for i in incidental):
        problems.append("incidental is a list of strings")
    examinee = quiz.get("examinee")
    if examinee not in {"human", "agent"}:
        problems.append("examinee is human or agent")

    questions = quiz.get("questions")
    if not isinstance(questions, list):
        return problems + ["questions is a list"]
    if len(questions) > MAX_QUESTIONS:
        problems.append(f"{len(questions)} questions, more than {MAX_QUESTIONS}")
    ids = set()
    for n, q in enumerate(questions, 1):
        where = f"question {n}"
        if not isinstance(q, dict):
            problems.append(f"{where}: is an object")
            continue
        for key in sorted(set(q) - QUESTION_KEYS):
            problems.append(f"{where}: unknown key {key!r}")
        qid = q.get("id")
        if not text(qid) or qid in ids:
            problems.append(f"{where}: id is a unique non-empty string")
        ids.add(qid)
        kind = q.get("kind")
        if kind not in KINDS:
            problems.append(f"{where}: kind is one of {sorted(KINDS)}")
            continue
        if examinee == "agent" and kind != "free":
            problems.append(f"{where}: an agent examinee gets free questions only")
        if q.get("category") not in CATEGORIES:
            problems.append(f"{where}: category is one of {sorted(CATEGORIES)}")
        if not text(q.get("prompt")):
            problems.append(f"{where}: prompt is a non-empty string")
        check_options(where, kind, q.get("options"), problems)
        points = q.get("key_points")
        if not isinstance(points, list) or not points or not all(text(p) for p in points):
            problems.append(f"{where}: key_points is a non-empty list of strings")
        attempts = q.get("attempts")
        if plan:
            if attempts:
                problems.append(f"{where}: a plan has no attempts yet")
            continue
        if not isinstance(attempts, list) or not attempts:
            problems.append(f"{where}: has at least one attempt")
            continue
        for m, a in enumerate(attempts, 1):
            at = f"{where} attempt {m}"
            if not isinstance(a, dict):
                problems.append(f"{at}: is an object")
                continue
            for key in sorted(set(a) - ATTEMPT_KEYS):
                problems.append(f"{at}: unknown key {key!r}")
            answer = a.get("answer")
            if not (text(answer) or (isinstance(answer, list) and all(text(x) for x in answer))):
                problems.append(f"{at}: answer is the text or the picked labels")
            if a.get("verdict") not in VERDICTS:
                problems.append(f"{at}: verdict is one of {sorted(VERDICTS)}")

    if examinee == "human" and len(questions) >= 2:
        kinds = [q.get("kind") for q in questions if isinstance(q, dict)]
        if kinds[0] != "single":
            problems.append("the quiz opens with a single question")
        if kinds[-1] not in {"multi", "free"}:
            problems.append("the quiz ends with a multi or a free question")

    outcome = quiz.get("outcome")
    if plan:
        if outcome is not None:
            problems.append("a plan has no outcome yet")
    elif outcome not in {"passed", "failed"}:
        problems.append("outcome is passed or failed")
    elif outcome == "passed":
        for n, q in enumerate(questions, 1):
            attempts = q.get("attempts") if isinstance(q, dict) else None
            if isinstance(attempts, list) and attempts and isinstance(attempts[-1], dict) \
                    and attempts[-1].get("verdict") != "pass":
                problems.append(f"question {n}: a passed quiz ends every question on a pass")
    return problems


def main(argv):
    plan = "--plan" in argv
    files = [a for a in argv if a != "--plan"]
    if len(files) != 1:
        sys.exit(__doc__.strip())
    try:
        with open(files[0]) as f:
            quiz = json.load(f)
    except (OSError, json.JSONDecodeError) as error:
        sys.exit(f"quizlint: {files[0]}: {error}")
    problems = lint(quiz, plan)
    if problems:
        print("\n".join(f"quizlint: {p}" for p in problems))
        return 1
    questions = quiz["questions"]
    kinds = ",".join(q["kind"] for q in questions) or "none"
    print(f"ok: {len(questions)} question(s), kinds {kinds}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

